/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 /opt/homebrew/opt/python@3.14/bin/python3.14 -c 'import contextlib,io,lib
class IntSubclass(int): pass
for value in (1, 2**4096):
 result=lib.validate_positive_integer(value); assert result is value
for value in (0,-1,-(2**4096)):
 try: lib.validate_positive_integer(value)
 except ValueError: pass
 else: raise AssertionError((value,\"expected ValueError\"))
for value in (True,False,1.0,\"1\",None,object(),IntSubclass(1),[],{},(1,)):
 try: lib.validate_positive_integer(value)
 except TypeError: pass
 else: raise AssertionError((value,\"expected TypeError\"))
out=io.StringIO(); err=io.StringIO()
with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err): assert lib.validate_positive_integer(7)==7
assert out.getvalue()==\"\" and err.getvalue()==\"\"
print(\"manual scalar contract probes: PASS\")'
find . -maxdepth 3 -type f -print | sort
git status --short"

